t.script:
(function () {
  var searchTimeout = null;
  // ... INIT CHIP ...
  function initChipInput() {
      var $realInput = $('#real-search-q');
      var $container = $('#chip-container');
      var $visualInput = $('#visual-search-input');
      var currentChips = [];
      var initialVal = $realInput.val();
      if(initialVal) {
          currentChips = initialVal.split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s; });
          renderChips();
      }
      function renderChips() {
          $container.find('.search-chip').remove();
          currentChips.forEach(function(term, index) {
              var $chip = $('<div class="search-chip"><span>' + $('<div>').text(term).html() + '</span><span class="btn-close-chip" data-index="' + index + '">&times;</span></div>');
              $visualInput.before($chip);
          });
          updateRealInput();
      }
      function updateRealInput() { $realInput.val(currentChips.join(', ')); }
      window.addSearchChip = function(term) {
          term = term.trim().replace(/,/g, '');
          if(term && !currentChips.includes(term)) { currentChips.push(term); renderChips(); }
          $visualInput.val(''); $visualInput.focus();
      }
      $container.on('click', '.btn-close-chip', function() {
          currentChips.splice($(this).data('index'), 1); renderChips(); $visualInput.focus();
      });
      $visualInput.on('keydown', function(e) {
          var val = $(this).val();
          if(e.key === 'Backspace' && val === '' && currentChips.length > 0) { currentChips.pop(); renderChips(); }
          else if (e.key === 'Enter') { e.preventDefault(); if (val.trim()) addSearchChip(val); $('#search-form').submit(); }
          else if (e.key === ',') { e.preventDefault(); if (val.trim()) addSearchChip(val); }
      });
      $container.on('click', function(e) { if(e.target === this) $visualInput.focus(); });
  }

  // ... DEBOUNCE & SEARCH AJAX ...
  function debounce(func, wait) {
    return function() { clearTimeout(searchTimeout); var context=this, args=arguments; searchTimeout = setTimeout(function() { func.apply(context, args); }, wait); };
  }
  function searchProducts(term, callback) {
    var isComboSearch = $('#comboSearchCheck').is(':checked');
    $.ajax({
      url: "/search_stock/suggest",
      type: "POST", dataType: "json", contentType: "application/json",
      data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { q: term, combo_search: isComboSearch }, id: new Date().getTime() }),
      success: function(resp) { callback((resp && resp.result && resp.result.products) ? resp.result.products : []); }
    });
  }
  function renderSuggestions(products) {
    var $dropdown = $('#search-suggestions');
    if (!products || products.length === 0) { $dropdown.hide().empty(); return; }
    var html = '';
    products.forEach(function(p) {
       var displayName = p.name || p.default_code || '';
       var imgUrl = p.image_url || '/web/static/img/placeholder.png';
       var q = p.qty_total || 0;
       var badgeClass = 'bg-secondary';
       if (q > 10) badgeClass = 'bg-success';
       else if (q > 5) badgeClass = 'bg-info';
       else if (q > 0) badgeClass = 'bg-warning text-dark';

       var qtyInfo = (q > 0) ? ('<span class="badge ' + badgeClass + ' text-white border ms-2">Tồn: ' + fmt(q) + '</span>') : '<span class="badge bg-light text-muted border ms-2">Hết hàng</span>';
       if (q > 0 && q <= 5) qtyInfo = '<span class="badge ' + badgeClass + ' border ms-2">Tồn: ' + fmt(q) + '</span>';

       // data-code: dùng default_code để search chính xác, tránh ilike 'Dù' match 'dùng'
       var searchTerm = (p.default_code && p.default_code.trim()) ? p.default_code.trim() : displayName;
       html += '<div class="suggestion-item border-bottom p-2" data-name="' + displayName + '" data-code="' + (p.default_code || '') + '" data-search-term="' + searchTerm + '" style="cursor:pointer;">';
       html += '  <div class="d-flex align-items-center">';
       html += '    <img src="' + imgUrl + '" class=" me-2 flex-shrink-0" style="width:40px; height:40px; object-fit:cover;"/>';
       html += '    <div class="flex-grow-1 overflow-hidden">';
       html += '      <div class="d-flex align-items-center mb-1">';
       html += '        <div class="fw-bold text-dark text-truncate" style="font-size:0.9rem;">' + (p.default_code || '') + '</div>';
       html +=          qtyInfo;
       html += '      </div>';
       html += '      <div class="text-muted text-truncate small">' + (p.name || '') + '</div>';
       html += '    </div>';
       html += '    <div class="ms-2 text-primary"><i class="fa fa-angle-right"></i></div>';
       html += '  </div></div>';
    });
    $dropdown.html(html).show();
  }

  // --- HÀM TÁCH RIÊNG: CHỊU TRÁCH NHIỆM TẢI AJAX ---
  // Hàm này chỉ tải và hiển thị, KHÔNG đóng lại
  function loadDetailRow($btn) {
       var pid = $btn.data('pid');
       var isCombo = String($btn.data('is-combo')) === 'true';
       var $row = $btn.closest('tr'); 

       // Kiểm tra nếu đã có detail-row rồi thì thôi, không tải nữa (tránh trùng)
       var $next = $row.next();
       if ($next.length && $next.hasClass('detail-row')) return;

       var colCount = $row.children('td').length;
       var $detail = $('<tr class="detail-row"><td colspan="' + colCount + '"><div class="p-3 bg-light text-center"><span class="spinner-border spinner-border-sm me-2"></span>Đang tải...</div></td></tr>');
       $row.after($detail);
       $btn.html('<i class="fa fa-minus"></i>');

       var currentWid = $('select[name="warehouse_id"]').val() || '';
       var detailMode = isCombo ? 'per_warehouse' : null;

       $.ajax({
          url: "/search_stock/product_breakdown",
          type: "POST", dataType: "json", contentType: "application/json",
          data: JSON.stringify({jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: currentWid, detail_mode: detailMode }, id: 1}),
          success: function(resp) {
              var res = (resp && resp.result) ? resp.result : {};
              if(res.ok) {
                  $detail.find('td').html(buildDetailTable(res));
              } else {
                  $detail.find('td').html('<div class="text-danger small p-3">Lỗi: ' + (res.error || 'Unknown') + '</div>');
              }
          }
       });
  }

  $(document).ready(function() {
    initChipInput(); 
    var $visualInput = $('#visual-search-input');
    var $dropdown = $('#search-suggestions');
    $visualInput.on('input', debounce(function() {
      var term = $(this).val().trim();
      if (term.length >= 2) searchProducts(term, renderSuggestions);
      else $dropdown.hide();
    }, 300));
    $(document).on('click', '.suggestion-item', function() {
      // Dùng default_code (ví dụ: DU_MIL) để search, không dùng name (Dù MILWAUKEE)
      // vì ilike 'Dù' sẽ match cả 'từ dùng' → hàng trăm sản phẩm MILWAUKEE
      var term = $(this).data('search-term') || $(this).data('name');
      if (term) { window.addSearchChip(term); $dropdown.hide(); $('#search-form').submit(); }
    });
    $(document).on('click', function(e) { if (!$(e.target).closest('#chip-container, #search-suggestions').length) $dropdown.hide(); });

    // --- SỰ KIỆN CLICK (THỦ CÔNG) ---
    // Khi bấm tay thì giữ logic Toggle: Đang mở -> Đóng, Đang đóng -> Mở
    $(document).on('click', '.btn-expand', function () {
       var $btn = $(this);
       var $row = $btn.closest('tr');
       var $next = $row.next();

       if ($next.is(':visible')) { 
           $next.hide(); 
           $btn.html('<i class="fa fa-plus"></i>'); 
       } else {
           $next.show();
           $btn.html('<i class="fa fa-minus"></i>');
       }
    });

    // --- VIEW LOCATION DETAILS ---
    $(document).on('click', '.btn-view-location', function(e) {
        e.preventDefault();
        var pid = $(this).data('pid');
        var wid = $(this).data('wid');
        var name = $(this).data('name');

        $('#locationDetailsProductName').text(name);
        $('#locationDetailsBody').html('<div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div><div class="mt-2 text-muted">Đang tải...</div></div>');

        var myModalElem = document.getElementById('locationDetailsModal');
        // Check if Bootstrap 5 exists, if not, use minimal approach
        if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
            var myModal = bootstrap.Modal.getInstance(myModalElem) || new bootstrap.Modal(myModalElem);
            myModal.show();
        } else {
            // Fallback if bootstrap JS is not perfectly loaded
            $(myModalElem).show().addClass('show');
            $(document.body).append('<div class="modal-backdrop fade show" id="customBackdrop"></div>');
            $(myModalElem).find('.btn-close, .btn-secondary').off('click').on('click', function() {
                $(myModalElem).hide().removeClass('show');
                $('#customBackdrop').remove();
            });
        }

        $.ajax({
            url: "/search_stock/location_details",
            type: "POST", dataType: "json", contentType: "application/json",
            data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: wid }, id: new Date().getTime() }),
            success: function(resp) {
                var data = resp.result;
                if (data && data.ok) {
                    if (data.locations && data.locations.length > 0) {
                        var html = '<table class="table table-sm table-bordered mb-0">';
                        html += '<thead class="table-light"><tr><th class="text-center">Vị trí</th><th class="text-center">Tồn</th><th class="text-center">Sẵn sàng</th></tr></thead><tbody>';
                        data.locations.forEach(function(loc) {
                            html += '<tr>';
                            html += '<td class="text-center">' + loc.location + '</td>';
                            html += '<td class="text-center fw-bold">' + fmt(loc.qty) + '</td>';
                            html += '<td class="text-center text-success">' + fmt(loc.available) + '</td>';
                            html += '</tr>';
                        });
                        html += '</tbody></table>';
                        $('#locationDetailsBody').html(html);
                    } else {
                        $('#locationDetailsBody').html('<div class="alert alert-warning mb-0 text-center">Không có tồn kho tại các vị trí trong kho này.</div>');
                    }
                } else {
                    $('#locationDetailsBody').html('<div class="alert alert-danger mb-0 text-center">Lỗi: ' + (data ? data.error : 'Không thể tải dữ liệu') + '</div>');
                }
            },
            error: function() {
                $('#locationDetailsBody').html('<div class="alert alert-danger mb-0 text-center">Lỗi kết nối. Vui lòng thử lại.</div>');
            }
        });
    });
  });

  function fmt(n) { return (parseFloat(n)||0).toLocaleString('en-US'); }

  function buildDetailTable(data) {
      var html = '';
      var rows = data.rows || [];

      // CASE 1: COMBO
      if(data.mode === 'components_by_warehouse') {
          html += '<div class="p-3 detail-container-mobile"><div class="row g-3">';
          rows.forEach(function(c){
              var imgUrl = c.image_url || '/web/static/img/placeholder.png';
              html += '<div class="col-12 col-md-12">';
              html += '  <div class="card h-100 border shadow-sm">';
              html += '    <div class="card-header bg-white d-flex align-items-center py-2">';
              html += '      <img src="' + imgUrl + '" class=" me-3" style="width:40px; height:40px; object-fit:contain;">';
              html += '      <div class="flex-grow-1">';
              html += '        <div class="fw-bold text-primary">' + c.name + '</div>';
              html += '        <div class="small text-muted">SL Combo: <b>' + fmt(c.component_qty_in_combo) + '</b></div>';
              html += '      </div>';
              html += '    </div>';
              html += '    <div class="card-body p-0">';
              (c.warehouses||[]).forEach(function(w){
                  html += '<div class="border-bottom p-2">';
                  html += '  <div class="fw-bold small mb-1">' + w.warehouse_name + '</div>';
                  html += '  <div class="d-flex">';
                  html += '    <div class="flex-fill text-center border-end"><div class="small text-muted">Sẵn sàng</div><div class="fw-bold text-success">' + fmt(w.qty_available) + '</div></div>';
                  html += '    <div class="flex-fill text-center"><div class="small text-muted">Thực tế</div><div>' + fmt(w.qty_total) + '</div></div>';
                  html += '  </div>';
                  html += '</div>';
              });
              html += '    </div></div></div>';
          });
          html += '</div></div>';
      } 

      // CASE 2: SẢN PHẨM THƯỜNG
      else {
          html += '<div class="detail-container-mobile">';
          html += '<div class="d-none d-md-block p-3 bg-white">';
          html += '<table class="table table-sm mb-0"><thead><tr><th>Kho hàng</th><th class="text-end">Tồn</th><th class="text-end">Giữ</th><th class="text-end">Sẵn sàng</th></tr></thead><tbody>';
          rows.forEach(function(r){
              var availClass = (r.qty_available > 0) ? 'text-success fw-bold' : 'text-muted';
              html += '<tr><td>' + r.warehouse_name + '</td><td class="text-end">' + fmt(r.qty_total) + '</td><td class="text-end">' + fmt(r.qty_reserved) + '</td><td class="text-end ' + availClass + '">' + fmt(r.qty_available) + '</td></tr>';
          });
          html += '</tbody></table></div>';

          html += '<div class="d-md-none">';
          rows.forEach(function(r){
               html += '<div class="wh-card">';
               html += '  <div class="wh-header">' + r.warehouse_name + '</div>';
               html += '  <div class="wh-stats">';
               html += '    <div class="wh-stat-col ' + (r.qty_total==0 ? 'dim':'') + '"><div class="wh-label">Tổng</div><div class="wh-val">' + fmt(r.qty_total) + '</div></div>';
               html += '    <div class="wh-stat-col ' + (r.qty_reserved==0 ? 'dim':'') + '"><div class="wh-label">Đã giữ</div><div class="wh-val text-muted">' + fmt(r.qty_reserved) + '</div></div>';
               html += '    <div class="wh-stat-col highlight"><div class="wh-label">Có thể bán</div><div class="wh-val">' + fmt(r.qty_available) + '</div></div>';
               html += '  </div>';
               html += '</div>';
          });
          html += '</div>';
          html += '</div>';
      }

      return html;
  }

  // --- FORECAST DETAILS ---
  $(document).on('click', '.btn-forecast-detail', function(e) {
      e.preventDefault();
      var pid = $(this).data('pid');
      var name = $(this).data('name');
      var wid = $('select[name="warehouse_id"]').val() || '';

      $('#forecastDetailsProductName').text(name);
      $('#forecastDetailsBody').html(
          '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:56px 24px;gap:14px;">'+
          '<div class="spinner-border" style="color:#6366f1;" role="status"></div>'+
          '<div style="color:#9ca3af;font-size:.85rem;">Đang tải...</div></div>'
      );

      var modalElem = document.getElementById('forecastDetailsModal');
      if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
          var modal = bootstrap.Modal.getInstance(modalElem) || new bootstrap.Modal(modalElem);
          modal.show();
      } else {
          $(modalElem).show().addClass('show');
          $('body').append('<div class="modal-backdrop fade show" id="forecastBackdrop"></div>');
          $(modalElem).find('[data-bs-dismiss="modal"]').off('click.forecast').on('click.forecast', function() {
              $(modalElem).hide().removeClass('show');
              $('#forecastBackdrop').remove();
          });
      }

      $.ajax({
          url: "/search_stock/forecast_details",
          type: "POST", dataType: "json", contentType: "application/json",
          data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: wid }, id: new Date().getTime() }),
          success: function(resp) {
              var data = resp && resp.result;
              if (!data || !data.ok) {
                  $('#forecastDetailsBody').html('<div class="alert alert-danger m-2">Lỗi: ' + (data ? data.error : 'Không tải được dữ liệu') + '</div>');
                  return;
              }
              $('#forecastDetailsBody').html(buildForecastHtml(data));
          },
          error: function() {
              $('#forecastDetailsBody').html('<div class="alert alert-danger m-2">Lỗi kết nối. Vui lòng thử lại.</div>');
          }
      });
  });

  function _stateStyle(state) {
      var m = {
          'Sẵn sàng': {bg:'#f0fdf4',color:'#16a34a',border:'#86efac'},
          'Xác nhận': {bg:'#eff6ff',color:'#2563eb',border:'#93c5fd'},
          'Đang chờ': {bg:'#fffbeb',color:'#b45309',border:'#fcd34d'},
          'Hoàn tất': {bg:'#f3f4f6',color:'#6b7280',border:'#d1d5db'},
          'Đã hủy':   {bg:'#fef2f2',color:'#dc2626',border:'#fca5a5'},
      };
      return m[state] || {bg:'#eff6ff',color:'#2563eb',border:'#93c5fd'};
  }
  function _metaCell(label, val, color, bold) {
      return '<div>'
          + '<div style="font-size:.66rem;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:#9ca3af;margin-bottom:3px;">'+label+'</div>'
          + '<div style="font-size:.85rem;color:'+(color||'#374151')+';font-weight:'+(bold?'700':'500')+';word-break:break-word;">'+val+'</div>'
          + '</div>';
  }

  // Dùng CSS class để responsive: card trên mobile, table trên desktop
  var _fcss = '<style id="fc-style">';
  _fcss += '.fc-table{width:100%;border-collapse:collapse;font-size:.82rem;}';
  _fcss += '.fc-table th{background:#f9fafb;padding:8px 12px;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#9ca3af;border-bottom:2px solid #e5e7eb;white-space:nowrap;}';
  _fcss += '.fc-table td{padding:10px 12px;border-bottom:1px solid #f3f4f6;vertical-align:middle;}';
  _fcss += '.fc-table tr:last-child td{border-bottom:none;}';
  _fcss += '.fc-table tr:hover td{background:#fafafa;}';
  _fcss += '.fc-table .fc-num{font-weight:800;font-size:.95rem;}';
  _fcss += '.fc-table .fc-pick{font-weight:700;color:#374151;}';
  _fcss += '.fc-badge{display:inline-flex;align-items:center;padding:2px 8px;border-radius:5px;font-size:.68rem;font-weight:700;border-width:1px;border-style:solid;}';
  _fcss += '@media(max-width:640px){.fc-desktop{display:none!important;}.fc-mobile{display:block!important;}}';
  _fcss += '@media(min-width:641px){.fc-mobile{display:none!important;}.fc-desktop{display:block!important;}}';
  _fcss += '</style>';

  function buildForecastHtml(data) {
      var html = _fcss;
      var isPos = data.qty_forecast >= 0;
      var fqColor = isPos ? '#16a34a' : '#dc2626';

      // === FORMULA ROW ===
      var fqBg   = isPos ? '#f0fdf4' : '#fef2f2';
      var fqBord = isPos ? '#4ade80' : '#f87171';
      var fqSh   = isPos ? 'rgba(22,163,74,.18)' : 'rgba(220,38,38,.18)';
      html += '<div style="padding:20px 28px 18px;border-bottom:2px solid #f3f4f6;background:#fafafa;">';
      html += '<div style="display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;">';
      html += _pill('Tồn kho',   fmt(data.qty_on_hand),    '#fff',   '#e5e7eb',  '#111827', '#9ca3af');
      html += '<span style="font-size:24px;font-weight:700;color:#16a34a;">+</span>';
      html += _pill('Nhập ĐMH', '+'+fmt(data.total_incoming), '#f0fdf4','#86efac','#16a34a','#16a34a');
      html += '<span style="font-size:24px;font-weight:700;color:#dc2626;">−</span>';
      html += _pill('Xuất ĐBH', '−'+fmt(data.total_outgoing), '#fef2f2','#fca5a5','#dc2626','#dc2626');
      html += '<span style="font-size:24px;font-weight:700;color:#6b7280;">=</span>';
      html += _pill('Dự báo',   fmt(data.qty_forecast),    fqBg, fqBord, fqColor, fqColor, true, fqSh);
      html += '</div></div>';

      var inCount  = data.incoming.length;
      var outCount = data.outgoing.length;

      // ── INCOMING ────────────────────────────────────────────────
      html += '<div style="padding:20px 28px 6px;">';
      html += _sectionHeader('Phiếu nhập kho từ ĐMH', inCount, '#16a34a');

      if (inCount > 0) {
          // Desktop: table
          html += '<div class="fc-desktop">';
          html += '<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">';
          html += '<table class="fc-table">';
          html += '<thead><tr>';
          html += '<th>Phiếu nhập</th><th>Đơn mua (Origin)</th><th>Nhà cung cấp</th>';
          html += '<th>Ngày ĐH MISA</th><th>Ngày hàng về DK</th><th style="text-align:right;">SL nhập</th>';
          html += '</tr></thead><tbody>';
          data.incoming.forEach(function(r) {
              var ss = _stateStyle(r.state);
              var originPart = r.origin && r.origin !== r.po_name ? ' <span style="color:#9ca3af;font-weight:400;font-size:.75rem;">/ '+r.origin+'</span>' : '';
              html += '<tr>';
              html += '<td><span class="fc-pick">'+r.picking_name+'</span><br>';
              html += '    <span class="fc-badge" style="background:'+ss.bg+';color:'+ss.color+';border-color:'+ss.border+';margin-top:3px;">'+r.state+'</span></td>';
              html += '<td class="fw-bold" style="color:#2563eb;">'+r.po_name+originPart+'</td>';
              html += '<td>'+r.partner+'</td>';
              html += '<td>'+r.misa_date+'</td>';
              html += '<td style="font-weight:700;color:#2563eb;">'+((r.date_planned||r.scheduled_date)||'—')+'</td>';
              html += '<td style="text-align:right;"><span class="fc-num" style="color:#16a34a;">+'+fmt(r.qty)+'</span></td>';
              html += '</tr>';
          });
          html += '</tbody><tfoot><tr>';
          html += '<td colspan="5" style="text-align:right;font-weight:700;color:#6b7280;font-size:.78rem;padding:8px 12px;">Tổng nhập:</td>';
          html += '<td style="text-align:right;"><span class="fc-num" style="color:#16a34a;">+'+fmt(data.total_incoming)+'</span></td>';
          html += '</tr></tfoot></table></div></div>';

          // Mobile: cards
          html += '<div class="fc-mobile">';
          data.incoming.forEach(function(r) {
              var ss = _stateStyle(r.state);
              html += _pickingCard(r.picking_name, r.state, ss, '+'+fmt(r.qty), '#16a34a', '#f0fdf4', [
                  ['Đơn mua', r.po_name, '#2563eb', true],
                  ['Origin',  r.origin,  '#374151', false],
                  ['NCC',     r.partner, '#374151', false],
                  ['MISA',    r.misa_date,'#374151',false],
                  ['Hàng về', r.date_planned||r.scheduled_date, '#2563eb', true],
              ]);
          });
          html += '<div style="text-align:right;font-size:.78rem;font-weight:700;color:#16a34a;padding-bottom:10px;">Tổng nhập: +'+fmt(data.total_incoming)+'</div>';
          html += '</div>';

      } else {
          html += _empty('Không có phiếu nhập nào từ đơn mua hàng');
      }
      html += '</div>';

      // ── OUTGOING ────────────────────────────────────────────────
      html += '<div style="padding:4px 28px 24px;">';
      html += '<div style="border-top:1px solid #f3f4f6;padding-top:18px;">';
      html += _sectionHeader('Phiếu xuất kho từ ĐBH', outCount, '#dc2626');

      if (outCount > 0) {
          // Desktop: table
          html += '<div class="fc-desktop">';
          html += '<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">';
          html += '<table class="fc-table">';
          html += '<thead><tr>';
          html += '<th>Phiếu xuất</th><th>Đơn bán</th><th>Khách hàng</th>';
          html += '<th>Giao hàng DK</th><th style="text-align:right;">SL xuất</th>';
          html += '</tr></thead><tbody>';
          data.outgoing.forEach(function(r) {
              var ss = _stateStyle(r.state);
              html += '<tr>';
              html += '<td><span class="fc-pick">'+r.picking_name+'</span><br>';
              html += '    <span class="fc-badge" style="background:'+ss.bg+';color:'+ss.color+';border-color:'+ss.border+';margin-top:3px;">'+r.state+'</span></td>';
              html += '<td class="fw-bold" style="color:#2563eb;">'+r.so_name+'</td>';
              html += '<td>'+r.partner+'</td>';
              html += '<td style="font-weight:700;color:#2563eb;">'+(r.scheduled_date||'—')+'</td>';
              html += '<td style="text-align:right;"><span class="fc-num" style="color:#dc2626;">−'+fmt(r.qty)+'</span></td>';
              html += '</tr>';
          });
          html += '</tbody><tfoot><tr>';
          html += '<td colspan="4" style="text-align:right;font-weight:700;color:#6b7280;font-size:.78rem;padding:8px 12px;">Tổng xuất:</td>';
          html += '<td style="text-align:right;"><span class="fc-num" style="color:#dc2626;">−'+fmt(data.total_outgoing)+'</span></td>';
          html += '</tr></tfoot></table></div></div>';

          // Mobile: cards
          html += '<div class="fc-mobile">';
          data.outgoing.forEach(function(r) {
              var ss = _stateStyle(r.state);
              html += _pickingCard(r.picking_name, r.state, ss, '−'+fmt(r.qty), '#dc2626', '#fef2f2', [
                  ['Đơn bán',    r.so_name,        '#2563eb', true],
                  ['Khách hàng', r.partner,        '#374151', false],
                  ['Giao hàng',  r.scheduled_date, '#2563eb', true],
              ]);
          });
          html += '<div style="text-align:right;font-size:.78rem;font-weight:700;color:#dc2626;padding-bottom:10px;">Tổng xuất: −'+fmt(data.total_outgoing)+'</div>';
          html += '</div>';

      } else {
          html += _empty('Không có phiếu xuất nào từ đơn bán hàng');
      }
      html += '</div></div>';

      return html;
  }

  function _pill(label, val, bg, border, valColor, labelColor, large, shadow) {
      var sz = large ? '28px' : '26px';
      var fw = large ? '900' : '800';
      return '<div style="text-align:center;background:'+bg+';border:1.5px solid '+border
          +';border-radius:12px;padding:12px 22px;min-width:90px;box-shadow:0 1px 4px '+(shadow||'rgba(0,0,0,.07)')+';"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:'+(labelColor||'#9ca3af')+';margin-bottom:4px;">'+label+'</div>'
          +'<div style="font-size:'+sz+';font-weight:'+fw+';color:'+(valColor||'#111827')+';line-height:1;">'+val+'</div></div>';
  }

  function _sectionHeader(title, count, color) {
      return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;">'
          + '<div style="width:4px;height:20px;background:'+color+';border-radius:3px;"></div>'
          + '<span style="font-size:.95rem;font-weight:700;color:#111827;">'+title+'</span>'
          + '<span style="background:'+(count>0?color:'#9ca3af')+';color:#fff;border-radius:999px;font-size:.72rem;font-weight:700;padding:2px 9px;">'+count+'</span>'
          + '</div>';
  }
  function _empty(msg) {
      return '<div style="background:#f9fafb;border:1.5px dashed #e5e7eb;border-radius:10px;padding:20px;text-align:center;color:#9ca3af;font-size:.85rem;margin-bottom:14px;">'+msg+'</div>';
  }
  function _pickingCard(name, state, ss, qty, qColor, hBg, meta) {
      var h = '<div style="background:#fff;border:1px solid #e5e7eb;border-left:4px solid '+qColor+';border-radius:10px;margin-bottom:10px;overflow:hidden;">';
      h += '<div style="display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:'+hBg+';">';
      h += '<div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;">';
      h += '<span style="font-weight:700;color:#374151;">'+name+'</span>';
      h += '<span class="fc-badge" style="background:'+ss.bg+';color:'+ss.color+';border-color:'+ss.border+';">'+state+'</span>';
      h += '</div><span style="font-weight:800;color:'+qColor+';font-size:1rem;">'+qty+'</span></div>';
      h += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px 14px;">';
      meta.forEach(function(c) {
          if (!c[1]) return;
          h += '<div><div style="font-size:.63rem;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#9ca3af;margin-bottom:2px;">'+c[0]+'</div>'
              +'<div style="font-size:.82rem;color:'+(c[2]||'#374151')+';font-weight:'+(c[3]?'700':'500')+';">'+c[1]+'</div></div>';
      });
      h += '</div></div>';
      return h;
  }

})();
